package io.github.diodeme.ji.telemetry;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;

/** Thread-safe deterministic reference sink for TCKs and local tests. */
public final class RecordingTelemetrySink implements TelemetrySink {
    private final List<MutableSpan> spans = new ArrayList<>();
    private long nextId = 1;
    private long nextEndSequence = 1;

    @Override
    public synchronized TelemetrySpan start(SpanParent parent, SpanSpec spec) {
        long parentId = parent.nativeContext().filter(MutableSpan.class::isInstance)
                .map(MutableSpan.class::cast).map(item -> item.id).orElse(0L);
        var span = new MutableSpan(nextId++, parentId, spec.name(), spec.attributes());
        spans.add(span);
        return span;
    }

    public synchronized List<RecordedSpan> spans() {
        return spans.stream().map(MutableSpan::snapshot).toList();
    }

    private final class MutableSpan implements TelemetrySpan {
        private final long id;
        private final long parentId;
        private final String name;
        private final Map<String, TelemetryValue> attributes = new LinkedHashMap<>();
        private final List<TelemetryEvent> events = new ArrayList<>();
        private final List<MetricPoint> metrics = new ArrayList<>();
        private SpanStatus status = SpanStatus.ok();
        private boolean explicitStatus;
        private boolean settled;
        private long endSequence;

        private MutableSpan(long id, long parentId, String name, Map<String, TelemetryValue> attributes) {
            this.id = id;
            this.parentId = parentId;
            this.name = name;
            this.attributes.putAll(attributes);
        }

        @Override public <T> T inSpan(SpanSpec spec, java.util.function.Function<TelemetrySpan, T> callback) {
            return new SafeTelemetryContext(RecordingTelemetrySink.this, childParent()).inSpan(spec, callback);
        }

        @Override public <T> java.util.concurrent.CompletionStage<T> inSpanAsync(
                SpanSpec spec, java.util.function.Function<TelemetrySpan, java.util.concurrent.CompletionStage<T>> callback) {
            return new SafeTelemetryContext(RecordingTelemetrySink.this, childParent()).inSpanAsync(spec, callback);
        }

        @Override public void setAttributes(Map<String, TelemetryValue> values) {
            synchronized (RecordingTelemetrySink.this) {
                if (!settled) attributes.putAll(Map.copyOf(values));
            }
        }

        @Override public void addEvent(String eventName, Map<String, TelemetryValue> values) {
            synchronized (RecordingTelemetrySink.this) {
                if (!settled) events.add(new TelemetryEvent(eventName, values));
            }
        }

        @Override public void recordMetric(MetricPoint point) {
            synchronized (RecordingTelemetrySink.this) {
                if (!settled) metrics.add(point);
            }
        }

        @Override public void setStatus(SpanStatus next) {
            synchronized (RecordingTelemetrySink.this) {
                if (!settled) {
                    status = next;
                    explicitStatus = true;
                }
            }
        }

        @Override public void settle(boolean failed) {
            synchronized (RecordingTelemetrySink.this) {
                if (settled) return;
                if (failed && !explicitStatus) status = SpanStatus.error();
                settled = true;
                endSequence = nextEndSequence++;
            }
        }

        @Override public SpanParent childParent() { return SpanParent.of(this); }

        private RecordedSpan snapshot() {
            return new RecordedSpan(id, parentId == 0 ? OptionalLong.empty() : OptionalLong.of(parentId), name,
                    attributes, events, metrics, status, settled,
                    settled ? OptionalLong.of(endSequence) : OptionalLong.empty());
        }
    }
}
